query:
query viewerLeagues {
  viewer {
    id
    __typename
    ... on Member {
      leagues(current: true) {
        id
        slug
        isElectronicPaymentsEnabled
        __typename
      }
      __typename
    }
    ... on ExternalStaff {
      leagues {
        id
        slug
        __typename
      }
      __typename
    }
  }
}
